"""Report rendering (Approach B: composition + format registry).

Each format is a plain function ``(report) -> list[str]`` registered in
``_FORMATS`` via the ``@format_renderer`` decorator. Shared behaviour lives in
small helper functions that the renderers call. There is no class hierarchy.
"""

from __future__ import annotations

from typing import Callable

__all__ = ["render", "available_formats", "UnknownFormat", "format_renderer"]

Renderer = Callable[[dict], list[str]]


class UnknownFormat(Exception):
    """Raised when ``render`` is asked for a format that is not registered."""


_FORMATS: dict[str, Renderer] = {}


def format_renderer(name: str) -> Callable[[Renderer], Renderer]:
    """Register ``func`` as the renderer for format ``name``."""

    def decorator(func: Renderer) -> Renderer:
        _FORMATS[name] = func
        return func

    return decorator


# --- shared helpers ---------------------------------------------------------


def _cells(row: list) -> list[str]:
    return [str(cell) for cell in row]


def _columns(report: dict) -> list[str]:
    return _cells(report.get("columns", []))


def _rows(report: dict) -> list[list[str]]:
    return [_cells(row) for row in report.get("rows", [])]


def _title(report: dict) -> str:
    return str(report.get("title", ""))


# --- renderers --------------------------------------------------------------


@format_renderer("text")
def _render_text(report: dict) -> list[str]:
    lines = [_title(report), ""]
    lines.extend("  ".join(row) for row in _rows(report))
    return lines


def _pipe_row(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


@format_renderer("markdown")
def _render_markdown(report: dict) -> list[str]:
    columns = _columns(report)
    lines = ["# " + _title(report), ""]
    lines.append(_pipe_row(columns))
    lines.append("|" + "|".join("---" for _ in columns) + "|")
    lines.extend(_pipe_row(row) for row in _rows(report))
    return lines


# --- public interface -------------------------------------------------------


def available_formats() -> list[str]:
    """Return the registered format names, sorted."""
    return sorted(_FORMATS)


def render(report: dict, fmt: str) -> str:
    """Render ``report`` in format ``fmt``; raise ``UnknownFormat`` if unknown."""
    try:
        renderer = _FORMATS[fmt]
    except KeyError:
        raise UnknownFormat(
            f"unknown format {fmt!r}; available: {', '.join(available_formats())}"
        ) from None
    return "\n".join(renderer(report)) + "\n"
EOF
